function Main(input) {
  // 1行目がinput[0], 2行目がinput[1], …に入る
  input = input.split("\n");
  N = parseInt(input[0].split(" "));
  var result = 0;
  for(var i=1; i<N; i++) {
    result += Math.floor((N-1)/i);
  }
  //出力
  console.log("%d", result);
}
